#!/usr/bin/env bash
#
# Focused check: scripts/deploy-v5-public.sh publishes exactly the commit it is
# given, and rollback finds the previous release whatever its naming.
#
# Runs the real script against a throwaway repository and web root. Only what
# a laptop cannot run is stood in for: npm (a build that copies a marker into
# dist/ and regenerates one generated file), nginx, systemctl, and the route gate
# (the gate is checked on its own by scripts/qa-precheck-public-static.mjs; here
# it records how it was called). The health check hits a local server.
#
# Where this machine cannot create symlinks (Windows without the right), `ln -s`
# is stood in for by a directory junction, which reads as a link to `[ -L ]`
# and `readlink -f`; the atomic swap by `mv -T` stays the real one.
#
# Usage: bash scripts/qa-deploy-v5-public.sh [path/to/deploy-v5-public.sh]
# Exit 0 only when every arm behaves as stated.

set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCRIPT="$(cd "$(dirname "${1:-${HERE}/deploy-v5-public.sh}")" && pwd)/$(basename "${1:-deploy-v5-public.sh}")"
T="$(mktemp -d)"
SERVER_PID=""
cleanup() {
  [ -n "${SERVER_PID}" ] && kill "${SERVER_PID}" 2>/dev/null
  rm -rf "${T}"
}
trap cleanup EXIT

pass=0
fail=0
arm() { # arm <name> <ok 0|1> <detail>
  if [ "$2" = 0 ]; then pass=$((pass + 1)); echo "PASS  $1${3:+  — $3}"; else fail=$((fail + 1)); echo "FAIL  $1${3:+  — $3}"; fi
}

export GIT_AUTHOR_NAME=qa GIT_AUTHOR_EMAIL=qa@example.invalid GIT_COMMITTER_NAME=qa GIT_COMMITTER_EMAIL=qa@example.invalid
export MSYS2_ARG_CONV_EXCL="/srv"
G() { git -c core.autocrlf=false "$@"; }

# --- the stand-ins -------------------------------------------------------------
mkdir -p "${T}/bin"
cat >"${T}/bin/npm" <<'NPM'
#!/usr/bin/env bash
set -e
echo "npm $*" >>"${QA_LOG}"
case "$1" in
  ci|install) mkdir -p node_modules ;;
  run)
    [ "$2" = "build:web" ] || exit 1
    mkdir -p dist
    cp MARKER dist/index.html
    printf '\n// regenerated by the build\n' >>src/content/posts.generated.ts
    case "${QA_MUTATE:-}" in
      tracked) echo '// edited by the build' >>package.json ;;
      untracked) echo stray >src/stray.ts ;;
      head) git -c core.autocrlf=false commit -q --allow-empty -m 'moved by the build' ;;
    esac ;;
  *) exit 1 ;;
esac
NPM
cat >"${T}/bin/nginx" <<'NGINX'
#!/usr/bin/env bash
case "$1" in
  -T) [ -z "${QA_NGINX_T_FAIL:-}" ] || { echo "nginx: [emerg] test failure" >&2; exit 1; }
      printf '# configuration file /etc/nginx/sites-enabled/apex:\nserver { listen 443 ssl; server_name flowsmartly.com; }\n' ;;
  -t) exit 0 ;;
esac
NGINX
cat >"${T}/bin/systemctl" <<'SYSTEMCTL'
#!/usr/bin/env bash
echo "systemctl $*" >>"${QA_LOG}"
SYSTEMCTL
chmod +x "${T}/bin/"*

mkdir -p "${T}/probe-target"
if ! ln -s "${T}/probe-target" "${T}/probe-link" 2>/dev/null || [ ! -L "${T}/probe-link" ]; then
  cat >"${T}/bash-env.sh" <<'SHIM'
ln() {
  if [ "$1" = "-sfn" ] && [ $# -eq 3 ]; then
    [ -L "$3" ] && rm -f "$3"
    cmd //c "mklink /J $(cygpath -w "$3") $(cygpath -w "$2")" >/dev/null
  else
    command ln "$@"
  fi
}
SHIM
  export BASH_ENV="${T}/bash-env.sh"
  echo "(no symlink right here: ln -sfn stood in for by a junction; mv -T is real)"
fi

node -e 'const s=require("http").createServer((q,r)=>{r.end("ok")});s.listen(0,"127.0.0.1",()=>{require("fs").writeFileSync(process.argv[1],String(s.address().port))})' "${T}/port" &
SERVER_PID=$!
for _ in $(seq 1 50); do [ -s "${T}/port" ] && break; sleep 0.1; done

# --- a repository with two commits, and a checkout parked on the older one -----
G init -q --bare "${T}/origin.git"
G init -q "${T}/seed"
(
  cd "${T}/seed" || exit 1
  mkdir -p apps/v5/src/content scripts
  printf 'node_modules/\ndist/\n' >apps/v5/.gitignore
  echo '{"name":"v5","version":"0.0.0"}' >apps/v5/package.json
  echo '{"lockfileVersion":3}' >apps/v5/package-lock.json
  for f in changelog.generated.ts posts.generated.ts posts.index.json; do echo "// $f" >"apps/v5/src/content/$f"; done
  cat >scripts/precheck-v5-routes.mjs <<'GATE'
import { appendFileSync, existsSync, readFileSync } from 'node:fs';
const a = process.argv.slice(2);
const v = (n) => (a.indexOf(n) >= 0 ? a[a.indexOf(n) + 1] : null);
appendFileSync(process.env.QA_GATE_LOG, JSON.stringify({
  args: a, publicStatic: a.includes('--public-static'), dist: v('--dist'),
  marker: existsSync(`${v('--dist')}/index.html`) ? readFileSync(`${v('--dist')}/index.html`, 'utf8').trim() : null,
  confHasServer: v('--conf') && existsSync(v('--conf')) ? /server_name flowsmartly\.com/.test(readFileSync(v('--conf'), 'utf8')) : false,
  marketingRoot: v('--marketing-root'), portalRoot: v('--portal-root'),
}) + '\n');
process.exit(Number(process.env.QA_GATE_EXIT ?? 0));
GATE
  echo C1 >apps/v5/MARKER
  G add -A && G commit -q -m C1
  echo C2 >apps/v5/MARKER
  G commit -q -am C2
  G push -q "${T}/origin.git" HEAD:refs/heads/main
)
C1="$(G -C "${T}/seed" rev-parse HEAD~1)"
C2="$(G -C "${T}/seed" rev-parse HEAD)"
G clone -q "${T}/origin.git" "${T}/app"
G -C "${T}/app" checkout -q --detach "${C1}"
echo WORKTREE >"${T}/app/apps/v5/MARKER" # another deploy's checkout, parked and dirty

export PATH="${T}/bin:${PATH}"
export SOURCE_REPO="${T}/app" BUILD_ROOT="${T}/build" WEB_ROOT="${T}/www" V5_PORTAL_ROOT="/srv/example/portal"
# A deploy must run the gate of the commit it builds. PRECHECK (the gate a
# rollback uses) is pointed at one that always refuses, so a deploy that
# consulted it instead could not pass.
printf 'process.exit(1);
' >"${T}/refusing-gate.mjs"
export PRECHECK="${T}/refusing-gate.mjs"
export HEALTH_URL="http://127.0.0.1:$(cat "${T}/port")/" QA_LOG="${T}/log" QA_GATE_LOG="${T}/gate.log"
mkdir -p "${T}/www/releases"

run() { # run <label> <args...> ; leaves $code and ${T}/<label>.err
  local label="$1"; shift
  bash "${SCRIPT}" "$@" >"${T}/${label}.out" 2>"${T}/${label}.err"
  code=$?
}
releases() { ls "${T}/www/releases" | sort | tr '\n' ' '; }
active() { [ -L "${T}/www/current" ] && basename "$(readlink -f "${T}/www/current")"; }
err_has() { grep -qF -- "$2" "${T}/$1.err"; }

# --- refusals before anything is built ------------------------------------------
for bad in "${C2:0:8}" "origin/main" ""; do
  run refuse deploy ${bad:+"$bad"}
  err_has refuse "full 40-character commit"; r=$?
  arm "REFUSE deploy '${bad:-<none>}' (not a full commit)" $([[ ${code} != 0 && ${r} == 0 ]]; echo $?) "exit ${code}; releases: $(releases)"
done
run missing deploy 0123456789abcdef0123456789abcdef01234567
err_has missing "is not in"; r=$?
arm "REFUSE a 40-hex commit the repository does not have" $([[ ${code} != 0 && ${r} == 0 ]]; echo $?) "exit ${code}"

# --- the defect: it must build <commit>, not the parked checkout ---------------
: >"${QA_GATE_LOG}"
run deploy deploy "${C2}"
rel="$(active)"
marker="$(cat "${T}/www/current/index.html" 2>/dev/null)"
arm "ALLOW deploy C2 while the checkout sits dirty on C1: publishes C2's bytes, gated by C2's gate" \
  $([[ ${code} == 0 && "${marker}" == "C2" ]]; echo $?) "exit ${code}; served '${marker}' from ${rel}"
[[ "${rel}" =~ ^[0-9]{8}T[0-9]{6}Z-${C2:0:8}$ ]]; arm "the release is named <UTC stamp>-<sha8>, like the live ones" $? "${rel}"
calls="$(grep -c . "${QA_GATE_LOG}")"
node -e '
  const l = require("fs").readFileSync(process.argv[1], "utf8").trim().split("\n").map(JSON.parse);
  const ok = l.length === 2 && l.every((c) => c.publicStatic && c.marker === "C2" && c.confHasServer && c.portalRoot === "/srv/example/portal" && /www[\\/]current$/.test(c.marketingRoot))
    && /src[\\/]apps[\\/]v5[\\/]dist$/.test(l[0].dist) && /www[\\/]releases[\\/]/.test(l[1].dist);
  process.exit(ok ? 0 : 1)' "${QA_GATE_LOG}"
arm "the gate ran --public-static on the build, then on the copy, against nginx -T" $? "${calls} call(s)"
parked="$(G -C "${T}/app" rev-parse HEAD) $(cat "${T}/app/apps/v5/MARKER")"
arm "the parked checkout is untouched" $([ "${parked}" = "${C1} WORKTREE" ]; echo $?) ""
arm "no build directory is left behind" $([ -z "$(ls -A "${T}/build" 2>/dev/null)" ]; echo $?) "$(ls -A "${T}/build" 2>/dev/null | tr '\n' ' ')"
grep -q "npm ci" "${QA_LOG}"; arm "dependencies come from the lockfile (npm ci)" $? ""

# --- refusals after the build: nothing is published, current is not moved ------
before_rel="$(releases)"
before_active="$(active)"
deny_after() { # deny_after <name> <expected stderr> [env...]
  local name="$1" want="$2"; shift 2
  env "$@" bash "${SCRIPT}" deploy "${C2}" >"${T}/deny.out" 2>"${T}/deny.err"; code=$?
  err_has deny "${want}"; local r=$?
  arm "DENY ${name}" $([[ ${code} != 0 && ${r} == 0 && "$(releases)" == "${before_rel}" && "$(active)" == "${before_active}" ]]; echo $?) \
    "exit ${code}; $(grep -o 'FATAL: .*' "${T}/deny.err" | cut -c1-110)"
}
deny_after "the build edits a tracked file" "differs from ${C2} after the build" QA_MUTATE=tracked
deny_after "the build leaves an untracked file" "differs from ${C2} after the build" QA_MUTATE=untracked
deny_after "the build moves HEAD" "HEAD is" QA_MUTATE=head
deny_after "the route gate fails" "route gate failed" QA_GATE_EXIT=1
deny_after "nginx -T fails" "nginx -T failed" QA_NGINX_T_FAIL=1
deny_after "V5_PORTAL_ROOT is unset" "V5_PORTAL_ROOT is not set" V5_PORTAL_ROOT=
arm "no build directory is left behind by a refusal" $([ -z "$(ls -A "${T}/build" 2>/dev/null)" ]; echo $?) ""

# --- rollback across both namings ------------------------------------------------
# The live release uses <stamp>-<sha8>; an earlier run of the old script wrote
# <sha>-<14-digit stamp>. Hash order is the reverse of time order on purpose.
for n in 20260101T000000Z-1a2b3c4d ffffffff-20260901000000 manual-copy; do
  mkdir -p "${T}/www/releases/${n}" && echo "${n}" >"${T}/www/releases/${n}/index.html"
done
export PRECHECK="${T}/seed/scripts/precheck-v5-routes.mjs" # the rollback gate
: >"${QA_GATE_LOG}"
run rb1 rollback
arm "rollback (no argument) picks the newest by TIME that is not active" \
  $([[ ${code} == 0 && "$(active)" == "ffffffff-20260901000000" ]]; echo $?) "exit ${code}; active $(active)"
grep -q '"publicStatic":true' "${QA_GATE_LOG}"; arm "rollback runs the gate --public-static too" $? ""
run rb2 rollback 1a2b3c4d
arm "rollback <sha8> finds a <stamp>-<sha> release" $([[ ${code} == 0 && "$(active)" == "20260101T000000Z-1a2b3c4d" ]]; echo $?) "exit ${code}; active $(active)"
run rb3 rollback "${C2}"
arm "rollback <full sha> finds the release named by its first 8" $([[ ${code} == 0 && "$(active)" == "${rel}" ]]; echo $?) "exit ${code}; active $(active)"
run rb4 rollback '1a2b3c4d|ff'
err_has rb4 "not a sha"; r=$?
arm "REFUSE a rollback argument that is neither a release nor a sha" $([[ ${code} != 0 && ${r} == 0 ]]; echo $?) "exit ${code}"

# --- pruning is by time, keeps the active release and what it cannot date ------
mkdir -p "${T}/www/releases/20250101T000000Z-aaaaaaaa"
sleep 1
KEEP_RELEASES=4 bash "${SCRIPT}" deploy "${C2}" >"${T}/prune.out" 2>"${T}/prune.err"; code=$?
left="$(releases)"
arm "prune removes the oldest by time and never an undatable name" \
  $([[ ${code} == 0 && "${left}" != *20250101T000000Z-aaaaaaaa* && "${left}" == *20260101T000000Z-1a2b3c4d* && "${left}" == *manual-copy* ]]; echo $?) \
  "exit ${code}; left: ${left}"

echo
echo "$pass/$((pass + fail)) arms behaved as stated"
[ "${fail}" -eq 0 ]
